{
  "category_edits": [
    {
      "category": "architecture_interaction",
      "rationale": "Reduce every HSTU residual FFN expansion from 4× to 2× hidden width across all four category models to test whether lower capacity reduces overfitting on short histories. Preserve SiLU, dropout, residual paths, attention-output gates and all other settings. The generated predictor imports HSTURec from train.py, so it constructs matching checkpoint shapes without writer changes.",
      "edits": [
        {
          "find": "        self.ffn = nn.Sequential(\n            nn.Linear(hidden_units, hidden_units * 4),\n            nn.SiLU(),\n            nn.Dropout(dropout_rate),\n            nn.Linear(hidden_units * 4, hidden_units),\n            nn.Dropout(dropout_rate),\n        )",
          "replace": "        self.ffn = nn.Sequential(\n            nn.Linear(hidden_units, hidden_units * 2),\n            nn.SiLU(),\n            nn.Dropout(dropout_rate),\n            nn.Linear(hidden_units * 2, hidden_units),\n            nn.Dropout(dropout_rate),\n        )"
        }
      ]
    }
  ],
  "change_summary": "Halve HSTU residual FFN expansion from 4× to 2× hidden width for all four independently trained category models, with matching inference construction through the existing model import."
}
